const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const groups = JSON.parse(await fs.readFile(S+"\\_GIG50_CLEAN.json","utf8"));

// 展开成扁平列表
const flat = [];
for (const g of groups) for (const it of g.items) flat.push({ host: it.host, name: it.name||it.host, cat: g.cat });
await fs.writeFile(S+"\\_GIG_FLAT.json", JSON.stringify(flat,null,1), "utf8");
return { count: flat.length, list: flat.map(f=>f.host) };
